def smallestWindow(S, P):
    from collections import Counter

    if not P or not S:
        return "-1"

    dict_p = Counter(P)
    required = len(dict_p)

    l, r = 0, 0
    formed = 0
    window_counts = {}

    ans = float("inf"), None, None

    while r < len(S):
        char = S[r]
        window_counts[char] = window_counts.get(char, 0) + 1

        if char in dict_p and window_counts[char] == dict_p[char]:
            formed += 1

        while l <= r and formed == required:
            char = S[l]

            if r - l + 1 < ans[0]:
                ans = (r - l + 1, l, r)

            window_counts[char] -= 1
            if char in dict_p and window_counts[char] < dict_p[char]:
                formed -= 1

            l += 1

    return S[ans[1]:ans[2]+1] if ans[0] != float("inf") else "-1"
